package com.orderflow.notification.service;import com.orderflow.notification.config.NotificationProperties;import com.orderflow.notification.dto.NotificationResponse;import io.micrometer.core.instrument.*;import jakarta.annotation.PreDestroy;import java.io.IOException;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;import org.springframework.stereotype.Component;import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;
@Component public class SseRegistry{private static final int MAX_PER_USER=5;private final Map<UUID,CopyOnWriteArrayList<SseEmitter>>emitters=new ConcurrentHashMap<>();private final NotificationProperties properties;private final Counter failures;private final AtomicInteger count=new AtomicInteger();public SseRegistry(NotificationProperties p,MeterRegistry m){properties=p;failures=m.counter("notification_sse_send_failures_total");Gauge.builder("notification_sse_connections",count,AtomicInteger::get).register(m);}public SseEmitter connect(UUID user){var list=emitters.computeIfAbsent(user,k->new CopyOnWriteArrayList<>());if(list.size()>=MAX_PER_USER){SseEmitter old=list.remove(0);old.complete();count.decrementAndGet();}SseEmitter e=new SseEmitter(properties.sseTimeout().toMillis());list.add(e);count.incrementAndGet();Runnable cleanup=()->remove(user,e);e.onCompletion(cleanup);e.onTimeout(cleanup);e.onError(x->cleanup.run());try{e.send(SseEmitter.event().name("connected").data(Map.of("connected",true)));}catch(IOException x){remove(user,e);}return e;}public void send(UUID user,NotificationResponse value){var list=emitters.getOrDefault(user,new CopyOnWriteArrayList<>());for(SseEmitter e:list){try{e.send(SseEmitter.event().name("notification").id(value.id().toString()).data(value));}catch(IOException|IllegalStateException x){failures.increment();remove(user,e);}}}@PreDestroy public void shutdown(){emitters.values().forEach(list->list.forEach(SseEmitter::complete));emitters.clear();count.set(0);}private void remove(UUID user,SseEmitter e){var list=emitters.get(user);if(list!=null&&list.remove(e)){count.decrementAndGet();if(list.isEmpty())emitters.remove(user,list);}}int connections(UUID user){return emitters.getOrDefault(user,new CopyOnWriteArrayList<>()).size();}}
